def clean_archive_key(path):
    """清洗对象存储键：处理 '.'、'..'、多余斜杠；返回不含首尾斜杠的键。
    '..' 弹出上一级，根级 '..' 忽略。"""
    parts = path.split("/")
    stack = []
    for part in parts:
        if part in ("", "."):
            continue
        stack.append(part)
    return "/".join(stack)

