from target import clean_archive_key

def test_plain_key():
    assert clean_archive_key("logs/app.log") == "logs/app.log"

def test_dots_removed():
    assert clean_archive_key("logs/./x.txt") == "logs/x.txt"

def test_parent_resolved():
    assert clean_archive_key("logs/tmp/../app.log") == "logs/app.log"
